import{_ as o,l,o as e,c as T,v as t,p as i,x as r,d as n,i as N,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"STUN / TURN","description":"","frontmatter":{"title":"STUN / TURN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stun-turn.md","filePath":"cs/stun-turn.md","lastUpdated":1789023840000}'),d={name:"cs/stun-turn.md"};function h(c,a,U,E,u,A){const s=l("Mermaid");return e(),T("div",null,[a[1]||(a[1]=t('<h1 id="stun-turn" tabindex="-1">STUN / TURN <a class="header-anchor" href="#stun-turn" aria-label="Permalink to &quot;STUN / TURN&quot;">​</a></h1><div class="epigraph"><p>STUN 问「我在 NAT 外看起来是谁」；TURN 在打不通时分配中继传输。ICE 把两者当候选来源，不是替代。</p><footer>—— 据 RFC 8489 STUN；RFC 8656 TURN 整理</footer></div><p><a href="/cs/webrtc-ice">上一课</a> 使用候选。<a href="/cs/ftp-passive">FTP 被动</a> 已见 NAT。<a href="/cs/napt">NAPT</a> 改端口。缺口是 <strong>STUN/TURN 协议本身</strong>。本课不把 DASH 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机只知私网地址。STUN：向公网服务器发绑定请求，应答告映射地址，得 srflx 候选。洞可短时保持，要刷新。仍可能两边都对称 NAT。TURN：分配 relay 地址，数据经服务器转发，费带宽与延迟，但总能通（若 UDP/TCP 被允许）。认证防滥用成开放中继。</p><p>不要把 STUN 写成 VPN。</p><p><span class="marginnote">RFC 8489、8656。TURN over TCP/TLS 应对禁 UDP。本课不写绕过企业政策的操作指南。</span></p><h3 id="发现映射与保底中继" tabindex="-1">发现映射与保底中继 <a class="header-anchor" href="#发现映射与保底中继" aria-label="Permalink to &quot;发现映射与保底中继&quot;">​</a></h3><p>STUN 不问通不通两端；TURN 费带宽换可达。未认证中继会成开放转发。ICE 同时试。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：仅 STUN / 加 TURN。画：绑定得到映射；Allocate 得到中继。与 GRE：TURN 是用户态中继，GRE 是 IP 隧道。</p>',11)),(e(),i(p,null,{default:r(()=>[N(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUN%5B%22%E7%BB%91%E5%AE%9A%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20MAP%5B%22%E5%8F%8D%E5%B0%84%E5%9C%B0%E5%9D%80%22%5D%0A%20%20FAIL%5B%22%E7%9B%B4%E8%BF%9E%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20TURN%5B%22%E4%B8%AD%E7%BB%A7%E5%88%86%E9%85%8D%22%5D%0A%20%20TURN%20--%3E%20RELAY%5B%22%E7%BB%8F%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%BD%AC%E5%8F%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DoH 不帮 NAT。GeoDNS 可找近的 TURN，减中继 RTT。计费：中继吃运营 \\(C\\)。ICE 同时试，成功则停 TURN 省钱。SSH 反向隧道是另一中继。</p><p>安全：未认证 TURN 会成放大器，必须凭证。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ICE-TCP 的全部。DASH/HLS 是下一课。后课默认：STUN 发现映射；TURN 保底中继。</p><p>只部署 STUN 在严格 NAT 上不够。</p><p>上一课留下的缺口在本课收口；「STUN / TURN」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/dash-hls">DASH / HLS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STUN 发现 NAT 映射。</li><li>TURN 提供中继候选。</li><li>ICE 选择最便宜通的路。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8489；RFC 8656。</li></ul>',10))])}const R=o(d,[["render",h]]);export{_ as __pageData,R as default};
